const item = $input.first();

if (!item.binary?.x) {
  return [{
    json: {
      success: false,
      error: "NO_FILE",
      message: "No audiogram file was received."
    }
  }];
}

const binary = item.binary.x;

return [{
  json: {
    success: true,
    fileName: binary.fileName || "audiogram",
    mimeType: binary.mimeType || "application/octet-stream"
  },
  binary: {
    data: binary
  }
}];

const raw =
  $json.content?.parts?.[0]?.text ??
  $json.text ??
  $json.output ??
  "";

if (!raw) {
  return [{
    json: {
      success: false,
      error: "NO_GEMINI_OUTPUT"
    }
  }];
}

let cleaned = raw
  .replace(/```json\s*/gi, "")
  .replace(/```\s*/g, "")
  .trim();

try {
  const data = JSON.parse(cleaned);

  return [{
    json: {
      success: true,
      ...data
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      error: "INVALID_GEMINI_JSON",
      raw: cleaned,
      message: error.message
    }
  }];
}

const d = $json;

const confidence = Number(d.confidence);

if (d.validAudiogram !== true) {
  return [{
    json: {
      success: false,
      error: "INVALID_AUDIOGRAM",
      message: "The uploaded image is not a valid audiogram.",
      confidence
    }
  }];
}

if (!Number.isFinite(confidence) || confidence < 0.65) {
  return [{
    json: {
      success: false,
      error: "LOW_CONFIDENCE",
      message: "The audiogram could not be read with sufficient confidence.",
      confidence
    }
  }];
}

if (
  !Array.isArray(d.leftEar) ||
  !Array.isArray(d.rightEar) ||
  d.leftEar.length === 0 ||
  d.rightEar.length === 0
) {
  return [{
    json: {
      success: false,
      error: "MISSING_THRESHOLDS",
      message: "Threshold data is missing for one or both ears.",
      confidence
    }
  }];
}

return [{
  json: {
    success: true,
    validAudiogram: true,
    imageQuality: d.imageQuality,
    leftEar: d.leftEar,
    rightEar: d.rightEar,
    confidence,
    notes: d.notes || []
  }
}];

const d = $json;

const frequencies = [500, 1000, 2000];

function calculatePTA(ear) {
  const values = frequencies.map(freq => {
    const point = ear.find(p => Number(p.frequency) === freq);

    return {
      frequency: freq,
      db: point ? Number(point.db) : 120
    };
  });

  const average =
    values.reduce((sum, point) => sum + point.db, 0) / values.length;

  return {
    values,
    pta: Number(average.toFixed(1))
  };
}

const left = calculatePTA(d.leftEar);
const right = calculatePTA(d.rightEar);

return [{
  json: {
    ...d,
    pta: {
      frequencies,
      left: left.pta,
      right: right.pta
    },
    ptaDetails: {
      left: left.values,
      right: right.values
    }
  }
}];

const d = $json;

// MVP: Belgium / RIZIV
// Later this can come from the user's selected country.
const country = "BE";

const criteriaProvider = {
  BE: {
    country: "BE",
    authority: "RIZIV",
    name: "Belgian RIZIV criteria"
  }
};

const criteria = criteriaProvider[country];

if (!criteria) {
  return [{
    json: {
      ...d,
      success: false,
      error: "NO_CRITERIA_FOR_COUNTRY",
      country
    }
  }];
}

return [{
  json: {
    ...d,
    country,
    criteria
  }
}];

const criteriaRow = $input.first().json;

// Get the measurements from the earlier node.
const audiogram = $("select criteria").first().json;

if (!criteriaRow || !criteriaRow.criteriaJson) {
  return [{
    json: {
      success: false,
      error: "RIZIV_CRITERIA_NOT_FOUND",
      message: "No stored RIZIV criteria were found."
    }
  }];
}

let parsedCriteria;

try {
  parsedCriteria = JSON.parse(criteriaRow.criteriaJson);
} catch (error) {
  return [{
    json: {
      success: false,
      error: "INVALID_RIZIV_CRITERIA_JSON",
      message: "The stored RIZIV criteria could not be parsed."
    }
  }];
}

return [{
  json: {
    ...audiogram,
    country: criteriaRow.Country,
    criteria: {
      authority: criteriaRow.authority,
      sourceUrl: criteriaRow.sourceUrl,
      checkedAt: criteriaRow.checkedAt,
      ...parsedCriteria
    }
  }
}];

const d = $input.first().json;

if (!d.success || !d.pta || !d.criteria?.rules) {
  return [{
    json: {
      success: false,
      error: "MISSING_REQUIRED_DATA",
      message: "Audiogram measurements or RIZIV criteria are missing."
    }
  }];
}

const rules = d.criteria.rules;
const left = Number(d.pta.left);
const right = Number(d.pta.right);

if (!Number.isFinite(left) || !Number.isFinite(right)) {
  return [{
    json: {
      success: false,
      error: "INVALID_PTA",
      message: "Valid PTA measurements are required."
    }
  }];
}

// This node performs audiogram-based screening only.
// Age and clinical/contextual conditions are not inferred.
const flags = [];

if (left >= rules.bilateralSevere.minPtaEachEar &&
    right >= rules.bilateralSevere.minPtaEachEar) {
  flags.push("BILATERAL_SEVERE_THRESHOLD_MET");
}

const worseEar = Math.max(left, right);
const betterEar = Math.min(left, right);

if (betterEar > rules.asymmetricBilateral.betterEar.ptaGreaterThan) {
  if (worseEar >= rules.asymmetricBilateral.worseEar.under18MinPta) {
    flags.push("ASYMMETRIC_THRESHOLD_MET_FOR_UNDER18");
  }

  if (worseEar >= rules.asymmetricBilateral.worseEar.age18PlusMinPta) {
    flags.push("ASYMMETRIC_THRESHOLD_MET_FOR_ADULT");
  }
}

if (worseEar >= rules.unilateralDeafness.affectedEar.under18MinPta &&
    betterEar <= rules.unilateralDeafness.normalEar.maxPta) {
  flags.push("UNILATERAL_THRESHOLD_MET_FOR_UNDER18");
}

if (worseEar >= rules.unilateralDeafness.affectedEar.age18PlusMinPta &&
    betterEar <= rules.unilateralDeafness.normalEar.maxPta) {
  flags.push("UNILATERAL_THRESHOLD_MET_FOR_ADULT");
}

return [{
  json: {
    ...d,
    screening: {
      status: flags.length
        ? "POTENTIAL_CRITERIA_MATCH"
        : "NO_THRESHOLD_MATCH",
      flags,
      ptaUsed: {
        left: left,
        right: right,
        frequencies: d.pta.frequencies
      },
      explanation: flags.length
        ? "One or more audiogram thresholds match a screening category. Additional patient and clinical criteria must be checked."
        : "The measured PTA values do not meet the threshold categories currently checked by Sonaris.",
      requiresClinicalContext: true,
      disclaimer: "Screening support only. This result does not establish a diagnosis or reimbursement eligibility."
    }
  }
}];

const d = $input.first().json;
const s = d.screening || {};

return [{
  json: {
    success: true,
    result: {
      status: s.status || "REVIEW_REQUIRED",
      message: s.explanation ||
        "The audiogram screening is complete.",
      pta: {
        left: d.pta?.left ?? null,
        right: d.pta?.right ?? null,
        frequencies: d.pta?.frequencies ?? []
      },
      confidence: d.confidence ?? null,
      flags: s.flags || [],
      criteria: {
        authority: d.criteria?.authority ?? "RIZIV",
        sourceUrl: d.criteria?.sourceUrl ?? null,
        checkedAt: d.criteria?.checkedAt ?? null
      },
      requiresClinicalContext:
        s.requiresClinicalContext ?? true,
      disclaimer:
        "Decision-support screening only. This result is not a diagnosis or confirmation of reimbursement eligibility."
    }
  }
}];
